/**
 * 从原始数据中解析JSON格式的日志
 * @param {string} data - 包含多行日志的字符串
 * @returns {Object} 包含解析成功的日志数组和解析失败的日志数组
 */
function doJson(data) {
  const logs = [];
  const errorLogs = [];
  const _logs = data.split('\n');
  
  for (let i = 0; i < _logs.length; i++) {
    const temp = _logs[i];
    try {
      // 使用正则表达式提取JSON部分并解析
      const jsonPart = temp.replace(/^[^{]*?:({.*)/g, '$1');
      const log = JSON.parse(jsonPart)
      logs.push(compatible(log));
    } catch (error) {
      if (temp.trim() !== '') {
        console.warn('解析错误：非json，json内容[ ' + temp + ' ]');
        errorLogs.push({'line': i, 'log': temp});
      } else {
        console.warn('解析错误：空字符串');
      }
    }
  }
  
  return {"data": logs, "errorLogs": errorLogs};
}

/**
 * 从Loki格式的数据中解析日志
 * @param {string} data - Loki API返回的JSON字符串
 * @returns {Object} 包含解析成功的日志数组和解析失败的日志数组
 */
function doLoki(data) {
  const logs = [];
  const errorLogs = [];
  const _logs = JSON.parse(data);
  
  for (let i = 0; i < _logs.length; i++) {
    const temp = _logs[i].line;
    try {
      const log = JSON.parse(temp)
      logs.push(compatible(log));
    } catch(error) {
      if (temp.trim() !== '') {
        console.warn('解析错误：非json，json内容[ ' + temp + ' ]');
        errorLogs.push({'line': i, 'log': temp});
      } else {
        console.warn('解析错误：空字符串');
      }
    }
  }
  
  return {"data": logs, "errorLogs": errorLogs};
}

/**
 * 做数据兼容，现有日志存在部分问题
 * 1. 规范定义的protocol存在拼写错误，写成了protocal
 * 2. 大小写问题level，golang这边写成了小写，type字段，c写成了小写。
 * @param {Object} log - 日志对象
 * @returns {Object} 做过兼容处理的日志对象
 */
function compatible(log) {
    if (log.protocal) {
      log.protocol = log.protocal
    }
    if (log.type == "PROTOCAL") {
      log.type = "PROTOCOL"
    }

    if (log.level) {
      log.level = log.level.toUpperCase()
    }
    if (log.type) {
      log.type = log.type.toUpperCase()
    }
    return log
}

/**
 * 分析日志数据，进行预处理和分类
 * @param {string} data - 原始日志数据
 * @param {Object} filter - 过滤条件对象
 * @returns {Object} 包含处理后的各种日志数据结构
 */
export function dataAnalysis(data, filter) {
  let logs = [];
  const sortLogs = [];
  const serverLogs = [];
  const uniqueLogs = {};
  const uniqueLogsHit = {};
  const uniqueApps = {};
  const uniqueTrackIds = {};
  const sortLogsMap = {};
  const uniqueGroups = {};
  let errorLogs = [];

  // 根据输入类型解析数据
  if (filter.logInputType == 1) {
    const ret = doJson(data);
    logs = ret.data;
    errorLogs = ret.errorLogs;
  } else if (filter.logInputType == 2) {
    const ret = doLoki(data);
    logs = ret.data;
    errorLogs = ret.errorLogs;
  }

  // 处理每条日志
  for (let i = 0; i < logs.length; i++) {
    const log = logs[i];
    
    try {
      // 统一角色命名
      if (log.type === 'PROTOCOL' && log.protocol.role === 'CLIENT') {
        log.protocol.role = 'SENDER';
      }
      if (log.type === 'PROTOCOL' && log.protocol.role === 'SERVER') {
        log.protocol.role = 'RECEIVER';
      }
      
      // 处理空的trackId
      if (log.trackId === '') {
        log.trackId = '未填写';
      }
      
      // 跳过已经过滤掉的模块日志
      if (filter && Object.keys(filter.groups).length !== 0 && !filter.applications[log.application.name]) {
        continue;
      }
      
      // 根据日志类型进行分类处理
      if (log.type === 'DEFAULT') {
        sortLogs.push(log);
        if (sortLogsMap[log.timestamp]) {
          sortLogsMap[log.timestamp].push(log);
        } else {
          sortLogsMap[log.timestamp] = [log];
        }
      } else if (log.type === 'PROTOCOL' && log.protocol.role === 'SENDER') {
        sortLogs.push(log);
        if (log.protocol.request.id) {
          uniqueLogs[log.protocol.request.id] = log.protocol.request.id;
        }
        if (sortLogsMap[log.timestamp]) {
          sortLogsMap[log.timestamp].push(log);
        } else {
          sortLogsMap[log.timestamp] = [log];
        }
      } else if (log.type === 'PROTOCOL' && log.protocol.role === 'RECEIVER') {
        serverLogs.push(log);
        if (sortLogsMap[log.timestamp]) {
          sortLogsMap[log.timestamp].push(log);
        } else {
          sortLogsMap[log.timestamp] = [log];
        }
      }
      
      // 收集各种唯一值
      if (log.trackId) {
        uniqueTrackIds[log.trackId] = log.trackId;
      }
      if (log.application.name) {
        uniqueApps[log.application.name] = log.application.name;
      }

      if (log.protocol) {
        if (!log.protocol.source.group || !log.protocol.destination.group) {
          console.warn('group不存在：' + log + ' ]');
        }
        uniqueGroups[log.protocol.source.group] = log.protocol.source.group;
        uniqueGroups[log.protocol.destination.group] = log.protocol.destination.group;
      }
    } catch (error) {
      console.warn('处理错误：' + log + ' ]');
    }
  }
  
  // 处理接收方日志
  for (let i = 0; i < serverLogs.length; i++) {
    const log = serverLogs[i];
    if (log.protocol.request.id) {
      if (uniqueLogs[log.protocol.request.id]) {
        uniqueLogsHit[log.protocol.request.id] = log.protocol.request.id;
      } else {
        sortLogs.push(log);
      }
    } else {
      sortLogs.push(log);
    }
  }

  // 按时间戳排序
  sortLogs.sort(function(a, b) {
    let time1 = new Date(a.timestamp).getTime();
    let time2 = new Date(b.timestamp).getTime();
    if (a.timestamp.length === 31) {
      time1 = time1 * 1000 + Number(a.timestamp.substring(23, 26));
      time2 = time2 * 1000 + Number(b.timestamp.substring(23, 26));
    }
    return time1 - time2;
  });

  return {
    'sortLogs': sortLogs,
    'serverLogs': serverLogs,
    'uniqueLogs': uniqueLogs,
    'uniqueLogsHit': uniqueLogsHit,
    'uniqueTrackIds': uniqueTrackIds,
    'uniqueApps': uniqueApps,
    'sortLogsMap': sortLogsMap,
    'uniqueGroups': uniqueGroups,
    'errorLogs': errorLogs
  };
}

/**
 * 根据过滤条件对日志数据进行过滤
 * @param {Object} data - 包含sortLogs等属性的日志数据对象
 * @param {Object} filter - 过滤条件对象，包含各种过滤规则
 * @returns {Object} 包含过滤后的日志、分组信息和级别统计
 */
export function dataFilter(data, filter) {
  const filterLogs = [];
  const filterGroups = {};
  // 统计log.level的数量，并存入对象，key为level，value为level的数量
  const levelCount = {};

  // 遍历排序后的日志进行过滤
  for (let i = 0; i < data.sortLogs.length; i++) {
    const log = data.sortLogs[i];
    
    // 检查 log.level 是否在 filter.logLevel 数组中，如果不在则跳过当前循环
    if (filter && filter.logLevel && filter.logLevel.length > 0 && !filter.logLevel.includes(log.level)) {
      continue;
    }

    // 编译正则表达式
    let contextReg, contextExcludeReg, uriIncludeReg, uriExcludeReg;
    if (filter && filter.contextReg && filter.contextReg.trim() !== '') {
      contextReg = new RegExp(filter.contextReg, 'gi');
    }
    if (filter && filter.contextExcludeReg && filter.contextExcludeReg.trim() !== '') {
      contextExcludeReg = new RegExp(filter.contextExcludeReg, 'gi');
    }
    if (filter && filter.uriIncludeReg && filter.uriIncludeReg.trim() !== '') {
      uriIncludeReg = new RegExp(filter.uriIncludeReg, 'gi');
    }
    if (filter && filter.uriExcludeReg && filter.uriExcludeReg.trim() !== '') {
      uriExcludeReg = new RegExp(filter.uriExcludeReg, 'gi');
    }

    if (!log) {
      break;
    }
    
    // 内容正则匹配
    if (contextReg && contextReg.exec(JSON.stringify(log)) == null) {
      continue;
    }
    
    // 内容排除正则匹配
    if (contextExcludeReg && contextExcludeReg.exec(JSON.stringify(log)) != null) {
      continue;
    }
    
    // trackId过滤
    if (filter && Object.keys(filter.trackIds).length !== 0 && !filter.trackIds[log.trackId]) {
      continue;
    }

    // 应用程序过滤
    if (filter && Object.keys(filter.applications).length !== 0 && !filter.applications[log.application.name]) {
      continue;
    }
    
    // 日志类型过滤
    if (log.type === 'DEFAULT' && filter && !filter.logTypeDefault) {
      continue;
    }
    if (log.type === 'PROTOCOL' && filter && !filter.logTypeProtocal) {
      continue;
    }
    
    // 协议日志的额外过滤
    if (log.type === 'PROTOCOL') {
      // 分组过滤
      if (filter && Object.keys(filter.groups).length !== 0 && (!filter.groups[log.protocol.source.group] || !filter.groups[log.protocol.destination.group])) {
        continue;
      }

      // URI包含过滤
      if (uriIncludeReg && uriIncludeReg.exec(log.protocol.request.uri) == null) {
        continue;
      }

      // URI排除过滤
      if (uriExcludeReg && uriExcludeReg.exec(log.protocol.request.uri) != null) {
        continue;
      }
    }
    
    // 通过所有过滤条件的日志
    filterLogs.push(log);
    
    // 收集分组信息
    if (log.type === 'DEFAULT') {
      filterGroups[log.application.name] = log.application.name;
    } else if (log.type === 'PROTOCOL') {
      filterGroups[log.protocol.source.group] = log.protocol.source.group;
      filterGroups[log.protocol.destination.group] = log.protocol.destination.group;
    }

    // 统计日志级别
    if (levelCount[log.level]) {
      levelCount[log.level]++;
    } else {
      levelCount[log.level] = 1;
    }
  }

  return {"filterLogs": filterLogs, "filterGroups": filterGroups, "levelCount": levelCount};
}

/**
 * 根据显示范围过滤日志数据
 * @param {Object} data - 包含filterLogs等属性的日志数据对象
 * @param {Object} filter - 过滤条件对象，包含logRange等属性
 * @returns {Object} 包含范围过滤后的日志、分组信息和级别统计
 */
export function displayDataFilter(data, filter) {
  const filterLogs = [];
  const filterGroups = {};
  // 统计log.level的数量，并存入对象，key为level，value为level的数量
  const levelCount = {};
  
  // 根据显示范围过滤日志
  for (let i = filter.logRange[0]; i < filter.logRange[1]; i++) {
    const log = data.filterLogs[i];
    filterLogs.push(log);
    
    // 收集分组信息
    if (log.type === 'DEFAULT') {
      filterGroups[log.application.name] = log.application.name;
    } else if (log.type === 'PROTOCOL') {
      filterGroups[log.protocol.source.group] = log.protocol.source.group;
      filterGroups[log.protocol.destination.group] = log.protocol.destination.group;
    }
    
    // 统计日志级别
    if (levelCount[log.level]) {
      levelCount[log.level]++;
    } else {
      levelCount[log.level] = 1;
    }
  }
  
  return {"filterLogs": filterLogs, "filterGroups": filterGroups, "levelCount": levelCount};
}

/**
 * 生成用于mermaid的序列图数据
 * @param {Object} data - 原始数据对象，包含uniqueLogsHit等信息
 * @param {Object} filterData - 过滤后的数据对象，包含filterLogs等信息
 * @param {Object} filter - 过滤条件对象，包含高亮设置等
 * @param {Document} document - DOM文档对象，用于插入CSS样式
 * @returns {string|null} 生成的mermaid序列图代码，如果数据不足则返回null
 */
export function diagramDataGeneration(data, filterData, filter, document) {
  const mermaidBuffer = [];
  mermaidBuffer.push('sequenceDiagram');
  mermaidBuffer.push('autonumber');
  //mermaidBuffer.push("%%{init: { 'sequence': {'messageAlign': 'left','noteAlign': 'left'} }}%%")
  //mermaidBuffer.push("%%{init:{'themeCSS':'.messageLine0:nth-of-type(2) { stroke: #f00; };.messageText:nth-of-type(1) { fill: green; font-size: 30px !important;}; g:nth-of-type(3) rect.actor { stroke:#00f;fill: #ff0; }; g:nth-of-type(5) .note { stroke:#00f;fill: #ff0; };#arrowhead path {stroke: blue; fill:#f00;};'}}%%")

  // 创建高亮参与者映射
  const highlightActor = {};
  for (let i = 0; i < filter.highlightLogProtocalGroup.length; i++) {
    highlightActor[filter.highlightLogProtocalGroup[i]] = filter.highlightColors[i];
  }

  let preProtocalLog;
  let actorIndex = 0;
  let lineIndex = 0;
  let protocolIndex = 1;
  let defaultIndex = Object.keys(filterData.filterGroups).length + 2;
  const actor = {};
  let themeCSS = [];

  // 遍历过滤后的日志生成序列图
  for (let i = 0; i < filterData.filterLogs.length; i++) {
    const log = filterData.filterLogs[i];
  
    // 截取日志消息的第一行
    if (log.protocol && log.protocol.message) {
      log.protocol.message = log.protocol.message.split('\n')[0];
    }
    if (log.message) {
      log.message = log.message.split('\n')[0];
    }
    
    // 验证日志完整性
    if (log.protocol && (!log.protocol.source.group || !log.protocol.destination.group)) {
      console.warn('非法日志:' + JSON.stringify(log));
      continue;
    }

    // 检查上下文高亮
    let highlightContextReg, highlightContext = false;
    if (filter && filter.highlightContextRegular && filter.highlightContextRegular.trim() !== '') {
      highlightContextReg = new RegExp(filter.highlightContextRegular, 'gi');
    }

    if (highlightContextReg && highlightContextReg.exec(JSON.stringify(log)) != null) {
      highlightContext = true;
    }

    if (log.type === 'DEFAULT') {
      // 处理默认类型日志
      if (highlightContext) {
        themeCSS.push(addFilterDefaultHighlightCss(defaultIndex));
      }
      defaultIndex = defaultIndex + 1;

      // 添加新的参与者
      if (!actor[log.application.name]) {
        actorIndex = actorIndex + 1;
        actor[log.application.name] = log.application.name;
        if (highlightActor[log.application.name]) {
          themeCSS.push(addActorHighlightCss(actorIndex, Object.keys(filterData.filterGroups).length, highlightActor[log.application.name]));
        }
      }
      
      // 添加注释节点
      mermaidBuffer.push('Note over [' + log.application.name + ']:(' + i + ')' + log.timestamp + '<br/>' + (log.message.length > 100 ? logGraph(log.level) + mermaidEncode(log.message.substring(0, 100)) + '...' : logGraph(log.level) + mermaidEncode(log.message)));
    } else if (log.type === 'PROTOCOL') {
      // 处理协议类型日志
      // 添加源参与者
      if (!actor[log.protocol.source.group]) {
        actorIndex = actorIndex + 1;
        actor[log.protocol.source.group] = log.protocol.source.group;
        if (highlightActor[log.protocol.source.group]) {
          themeCSS.push(addActorHighlightCss(actorIndex, Object.keys(filterData.filterGroups).length, highlightActor[log.protocol.source.group]));
        }
      }
      
      // 添加目标参与者
      if (!actor[log.protocol.destination.group]) {
        actorIndex = actorIndex + 1;
        actor[log.protocol.destination.group] = log.protocol.destination.group;
        if (highlightActor[log.protocol.destination.group]) {
          themeCSS.push(addActorHighlightCss(actorIndex, Object.keys(filterData.filterGroups).length, highlightActor[log.protocol.destination.group]));
        }
      }

      lineIndex = lineIndex + 1;
      if (highlightActor[log.protocol.source.group]) {
        themeCSS.push(addLineHighlightCss(lineIndex, highlightActor[log.protocol.source.group]));
      }

      // 确定角色
      let role = log.protocol.role;
      if (log.protocol.role === 'SENDER' && data.uniqueLogsHit[log.protocol.request.id]) {
        role = 'RECEIVER,SENDER';
      }
      role = role + '|' + i;

      let prefix = log.protocol.type;

      // 计算前一个协议的持续时间
      let preProtocalDuration = 0;
      let highlightPreProtocalDuration = false;
      if(preProtocalLog) {
        let tempTime1 = new Date(log.timestamp).getTime();
        let tempTime2 = new Date(preProtocalLog.timestamp).getTime();
        preProtocalDuration = tempTime1 - tempTime2;
        if (log.timestamp.length === 31) {
          tempTime1 = tempTime1 * 1000 + Number(log.timestamp.substring(23, 26));
          tempTime2 = tempTime2 * 1000 + Number(preProtocalLog.timestamp.substring(23, 26));
          preProtocalDuration = (tempTime1 - tempTime2) / 1000;
        }
        if (filter.highlightPreProtocalDuration > 0 && filter.highlightPreProtocalDuration < preProtocalDuration) {
          highlightPreProtocalDuration = true;
        }
      }
      preProtocalLog = log;

      // 处理协议持续时间
      let highlightProtocalDuration = false;
      if (log.protocol.duration) {
        let logProtocalDuration = log.protocol.duration;
        if (log.protocol.request.timestamp.length === 31) {
          logProtocalDuration = log.protocol.duration / 1000;
        }
        
        prefix = prefix + ',' + formatDuration(logProtocalDuration) + ',↑' + formatDuration(preProtocalDuration);
        if (filter.highlightProtocalDuration > 0 && filter.highlightProtocalDuration < logProtocalDuration) {
          highlightProtocalDuration = true;
        }
      } else {
        prefix = prefix + ',↑' + formatDuration(preProtocalDuration);
      }

      // 构建上下文内容
      let context = '';
      if (filter.displayMode === '2') {
        if (log.labels && log.labels.code) {
          context = log.labels.code;
        } else {
          if (log.protocol.request.method) {
            context = '(' + log.protocol.request.method + ')' + log.protocol.request.uri;
          } else {
            context = log.protocol.request.uri;
          }
        }
      } else {
        if (log.protocol.request.method) {
          context = '(' + log.protocol.request.method + ')' + log.protocol.request.uri;
        } else {
          context = log.protocol.request.uri;
        }
      }
      context = logGraph(log.level) + mermaidEncode(context);
      prefix = mermaidEncode(prefix);

      // 处理成功响应
      if (log.protocol.code.includes('SUCCESS')) {
        if (highlightContext) {
          themeCSS.push(addFilterProtocalHighlightCss(protocolIndex, 3));
        }
        protocolIndex = protocolIndex + 3;
        if (highlightPreProtocalDuration) {
          mermaidBuffer.push('rect rgb(255, 153, 51, 0.4)');
        }
        if (highlightProtocalDuration) {
          mermaidBuffer.push('rect rgb(255, 255, 0, 0.4)');
        }
        mermaidBuffer.push('[' + mermaidEncode(log.protocol.source.group) + ']' + ' ->> ' + '[' + mermaidEncode(log.protocol.destination.group) + ']' + ':(' + role + ')' + log.timestamp + '<br/>[' + prefix + ']' + context);
        if (highlightProtocalDuration) {
          mermaidBuffer.push('end');
        }
        if (highlightPreProtocalDuration) {
          mermaidBuffer.push('end');
        }
      } else {
        // 处理错误响应
        if (highlightContext) {
          themeCSS.push(addFilterProtocalHighlightCss(protocolIndex, 4));
        }
        protocolIndex = protocolIndex + 4;
        if (highlightPreProtocalDuration) {
          mermaidBuffer.push('rect rgb(255, 153, 51, 0.4)');
        }
        if (highlightProtocalDuration) {
          mermaidBuffer.push('rect rgb(255, 255, 0, 0.4)');
        }
        mermaidBuffer.push('rect rgb(255, 0, 0, 0.5)');
        mermaidBuffer.push('[' + mermaidEncode(log.protocol.source.group) + ']' + ' -x ' + '[' + mermaidEncode(log.protocol.destination.group) + ']' + ':(' + role + ')' + log.timestamp + '<br/>[' + prefix + ']' + context + '<br/>' + mermaidEncode(log.protocol.code) + ': ' + mermaidEncode(log.protocol.message));
        mermaidBuffer.push('end');
        if (highlightProtocalDuration) {
          mermaidBuffer.push('end');
        }
        if (highlightPreProtocalDuration) {
          mermaidBuffer.push('end');
        }
      }
    }
  }

  // 插入CSS样式
  //mermaid在初始化themeCss的时候，如果携带>或者;等特殊符号会出现css不完整的情况
  //mermaidBuffer.push("%%{init:{'themeCSS':'" + themeCSS.join('') + "'}}%%")
  const cssDom = document.getElementById('mermaidCss');
  if (cssDom) {
    cssDom.innerHTML = themeCSS.join('');
  } else {
    const dom = document.createElement('style');
    dom.id = 'mermaidCss';
    dom.type = 'text/css';
    dom.innerHTML = themeCSS.join('');
    document.head.appendChild(dom);
  }

  // 检查是否有足够的数据生成图表
  if (mermaidBuffer.length < 3) {
    return;
  }
  
  console.info(mermaidBuffer.join('\n'));
  return mermaidBuffer.join('\n');
}

function mermaidEncode(str) {
  if(!str) {
    return ''
  }
  return str.replaceAll('#', '%%36%%').replaceAll(';', '#59;').replaceAll('+', '#43;').replaceAll(':', '#58;').replaceAll('>', '#62;').replaceAll('<', '#60;').replaceAll('%%36%%', '#36;')
}

function addLineHighlightCss(index, color) {
  const css = []
  css.push('.svg-pan-zoom_viewport>line:nth-of-type(')
  css.push(index)
  css.push('){stroke:')
  css.push(color.backgroundColor)
  css.push('!important;}')
  return css.join('')
}

function addFilterDefaultHighlightCss(index) {
  const css = []
  css.push('.svg-pan-zoom_viewport>g:nth-of-type(')
  css.push(index)
  css.push(') tspan{animation:highlight 1s infinite alternate;}')
  return css.join('')
}


function addFilterProtocalHighlightCss(index, count) {
  const css = []
  for(let i=0; i < count; i++) {
    css.push('.svg-pan-zoom_viewport>text:nth-of-type(')
    css.push(index)
    css.push('){animation:highlight 1s infinite alternate;}')
    index = index + 1
  }
  return css.join('')
}

function addActorHighlightCss(index, count, color) {
  const css = []
  // css中>指的只选择子节点，而不选择子节点的子节点
  // actor背景色
  css.push('.svg-pan-zoom_viewport>g:nth-of-type(')
  css.push(index + 1)
  css.push(') g rect.actor{fill:')
  css.push(color.backgroundColor)
  css.push('!important;stroke:')
  css.push('rgba(255, 255, 255, 1)')
  css.push('!important;}')
  css.push('.svg-pan-zoom_viewport>g:nth-last-of-type(')
  css.push(count - (index - 1))
  css.push(') rect.actor{fill:')
  css.push(color.backgroundColor)
  css.push('!important;stroke:')
  css.push('rgba(255, 255, 255, 1)')
  css.push('!important;}')
  // actor字体颜色
  css.push('.svg-pan-zoom_viewport>g:nth-of-type(')
  css.push(index + 1)
  css.push(') g text tspan{fill:')
  css.push(color.fontColor)
  css.push('!important;}')
  css.push('.svg-pan-zoom_viewport>g:nth-last-of-type(')
  css.push(count - (index - 1))
  css.push(') text tspan{fill:')
  css.push(color.fontColor)
  css.push('!important;}')
  // line背景色
  css.push('.svg-pan-zoom_viewport>g:nth-of-type(')
  css.push(index + 1)
  css.push(') line{stroke:')
  css.push(color.backgroundColor)
  css.push('!important;}')
  return css.join('')
}

/**
 * 将毫秒转换为可读的持续时间格式
 * @param {number} milliseconds - 毫秒数
 * @returns {string} 格式化后的持续时间字符串，如"1h30m20s"
 */
function formatDuration(milliseconds) {
  if (milliseconds <= 0) {
    return '0μs';
  }

  // 格式化的字符串数组
  const formatArr = [];
  // 定义临时的余数和整数
  let n = 0, r = 0;
  // 获得微妙，使用toFixed(0)解决8.139*1000等于8138.999999999999的精度问题
  let time = (milliseconds * 1000).toFixed(0);
  
  // 微妙
  n = Math.floor(time / 1000);
  r = time % 1000;
  time = n;
  if (r != 0) {
    formatArr.push(r + 'μs');
  }
  if (n == 0) {
    return formatArr.join('');
  }
  
  // 毫秒
  n = Math.floor(time / 1000);
  r = time % 1000;
  time = n;
  if (r != 0) {
    formatArr.push(r + 'ms');
  }
  if (n == 0) {
    formatArr.reverse();
    return formatArr.join('');
  }
  
  // 秒
  n = Math.floor(time / 60);
  r = time % 60;
  time = n;
  if (r != 0) {
    formatArr.push(r + 's');
  }
  if (n == 0) {
    formatArr.reverse();
    return formatArr.join('');
  }
  
  // 分钟
  n = Math.floor(time / 60);
  r = time % 60;
  time = n;
  if (r != 0) {
    formatArr.push(r + 'm');
  }
  if (n == 0) {
    formatArr.reverse();
    return formatArr.join('');
  }
  
  // 小时 - 修复此处的逻辑错误
  if (n > 0) {
    formatArr.push(n + 'h');
  }

  formatArr.reverse();
  return formatArr.join('');
}

/**
 * 将日志级别映射为表情符号
 * @param {string} level - 日志级别，如'error', 'warn', 'info'等
 * @returns {string} 对应的表情符号
 */
function logGraph(level) {
  // 将 level 转换为小写后再进行判断
  switch(level.toUpperCase()) {
    case 'PANIC':
      return '💥';
    case 'FATAL':
      return '☠️';
    case 'ERROR':
      return '❌';
    case 'WARN':
      return '⚠️';
    case 'INFO':
      return 'ℹ️';
    case 'DEBUG':
      return '🐛';
    case 'TRACE':
      return '🌀';
    default:
      return 'ℹ️';
  }
}